"""
generate_all.py — Full color catalog for all 9 brands.
SKUs and hex codes sourced from official brand PDF hex tables and product pages.
Run: python generate_all.py
"""

import os
import re
from template_v3 import build_workbook, next_versioned_path

OUTPUT_DIR = os.path.join(os.path.dirname(__file__), "output")
os.makedirs(OUTPUT_DIR, exist_ok=True)

# ── Shared settings shortcuts ──────────────────────────────────────────────────
def _pla(color, hex_, sku, product="PLA Basic", mat="PLA Basic",
         print_temp="190–220°C", bed_temp="35–45°C", drying="55°C / 8h",
         ams_xp="✓", ams_lite="✓", ams_2pro="✓", ams_ht="✓",
         tier="S", rationale="First-party; RFID-embedded profile; full AMS compatibility",
         spool="Plastic", adapter="No", tolerance="±0.03mm", notes="", disc=False):
    return dict(material_type=mat, sku=sku, product_name=product,
                color_name=color, color_hex=hex_, diameter="1.75mm",
                diameter_tolerance=tolerance, spool_type=spool, ams_adapter=adapter,
                print_temp=print_temp, bed_temp=bed_temp, drying=drying,
                ams_xp=ams_xp, ams_lite=ams_lite, ams_2pro=ams_2pro, ams_ht=ams_ht,
                tier=tier, tier_rationale=rationale, notes=notes, discontinued=disc)

# ─────────────────────────────────────────────────────────────────────────────
# BAMBU LAB
# Hex codes from official Bambu hex code PDFs (store.bblcdn.com / bblcdn.eu)
# SKU format: BL-<MATERIAL>-<COLOR_CODE>
# ─────────────────────────────────────────────────────────────────────────────
_BL_PLA_BASIC_RATIONALE = "First-party PLA Basic; RFID profile; up to 258mm/s; all AMS variants"
_BL_PLA_MATTE_RATIONALE = "First-party PLA Matte; matte finish; RFID profile; all AMS variants"
_BL_PETG_RATIONALE      = "First-party PETG Basic (reformulated 2026); improved strength vs HF"
_BL_ABS_RATIONALE       = "First-party ABS; RFID profile; enclosure required; AMS Lite ✗"
_BL_ASA_RATIONALE       = "First-party ASA; UV-resistant; enclosure required; AMS Lite ✗"

def _bl_pla(color, hex_, sku_code):
    return _pla(color, hex_, f"BL-PLAB-{sku_code}", "PLA Basic", "PLA Basic",
                "190–220°C", "35–45°C", "55°C / 8h",
                rationale=_BL_PLA_BASIC_RATIONALE)

def _bl_matte(color, hex_, sku_code):
    return _pla(color, hex_, f"BL-PLAM-{sku_code}", "PLA Matte", "PLA Matte",
                "190–220°C", "35–45°C", "55°C / 8h",
                rationale=_BL_PLA_MATTE_RATIONALE)

def _bl_petg(color, hex_, sku_code):
    return _pla(color, hex_, f"BL-PETG-{sku_code}", "PETG Basic", "PETG Basic",
                "220–260°C", "70–85°C", "65°C / 8h",
                rationale=_BL_PETG_RATIONALE)

def _bl_abs(color, hex_, sku_code):
    return _pla(color, hex_, f"BL-ABS-{sku_code}", "ABS", "ABS",
                "240–270°C", "90–100°C", "65°C / 8h",
                ams_lite="✗",
                rationale=_BL_ABS_RATIONALE,
                notes="Enclosure required (P1S/X1C/H2D); not for A1/A1 mini")

def _bl_asa(color, hex_, sku_code):
    return _pla(color, hex_, f"BL-ASA-{sku_code}", "ASA", "ASA",
                "240–270°C", "90–100°C", "80°C / 8h",
                ams_lite="✗",
                rationale=_BL_ASA_RATIONALE,
                notes="Enclosure required; UV-resistant outdoor use")

