# eSUN
# SKU format: eSUN brand codes e.g. ePLA+-BK1000
# ─────────────────────────────────────────────────────────────────────────────
def _esun(color, hex_, sku, mat="PLA+", product="ePLA+",
          print_temp="200–240°C", bed_temp="30–60°C", drying="45°C / 4h",
          ams_xp="✓", ams_lite="✓", ams_2pro="✓", ams_ht="✓",
          tier="A", rationale="", notes=""):
    return dict(material_type=mat, sku=sku, product_name=product,
                color_name=color, color_hex=hex_, diameter="1.75mm",
                diameter_tolerance="±0.03mm", spool_type="Plastic", ams_adapter="No",
                print_temp=print_temp, bed_temp=bed_temp, drying=drying,
                ams_xp=ams_xp, ams_lite=ams_lite, ams_2pro=ams_2pro, ams_ht=ams_ht,
                tier=tier, tier_rationale=rationale, notes=notes)

_ES_PLA_R  = "High-consistency PLA+; suspected OEM source for some Bambu PLA lines"
_ES_PETG_R = "Reliable PETG; excellent value; consistent diameter"
_ES_ABS_R  = "Decent ABS; enclosure required; no optimized Bambu profile"
_ES_ASA_R  = "Good UV-resistant ASA; requires enclosure"

