# ── All brands ─────────────────────────────────────────────────────────────────
BRANDS = [BAMBU, SUNLU, POLYMAKER, ESUN, OVERTURE, HATCHBOX, PRUSAMENT, CREALITY, MATTERHACKERS]

# ── Generate ───────────────────────────────────────────────────────────────────
if __name__ == "__main__":
    for brand_data in BRANDS:
        name = brand_data["brand"].replace(" ", "_")
        pattern = rf'^{re.escape(name)}_filaments_v3_(\d+)\.xlsx$'
        template = f'{name}_filaments_v3_{{n}}.xlsx'
        path, version, prev = next_versioned_path(OUTPUT_DIR, pattern, template)

        wb = build_workbook(brand_data)
        wb.save(path)
        n_cat = len(brand_data.get("catalog", []))
        print(f"✓  {os.path.basename(path)}  ({n_cat} catalog entries)")
        if prev:
            print(f"   ⚠  Delete old version from the repo after uploading: {prev}")
    print(f"\nAll {len(BRANDS)} files written to: {OUTPUT_DIR}/")
